import com.twintrade.app.MarketStore;import org.json.*;
public class NativeReliabilityTest{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}static boolean pending(String s){return s.startsWith("PENDING:");}static long due(String s){return Long.parseLong(s.substring(8));}
 public static void main(String[] args)throws Exception{MarketStore.init(new android.content.Context());MarketStore.reset();long now=System.currentTimeMillis();String good="{\"fee\":0,\"slip\":0,\"borrow\":0,\"funding\":0,\"liq\":90}";MarketStore.updateCaps("[{\"pairIndex\":300,\"maxLeverage\":500},{\"pairIndex\":33,\"maxLeverage\":150}]");MarketStore.tick(300,100,now);String opened=MarketStore.open(300,true,10,10,good);check(pending(opened),"DEGEN paper open queued");check(!pending(MarketStore.open(300,true,10,10,good)),"duplicate pending open rejected despite reserved cash");check(new JSONObject(MarketStore.book()).getJSONArray("pending").length()==1,"duplicate open did not add work");MarketStore.advancePendingForTests(300,101,due(opened));String id=new JSONObject(MarketStore.book()).getJSONArray("positions").getJSONObject(0).getString("id");String closing=MarketStore.close(id);check(pending(closing),"DEGEN close queued");check(MarketStore.close(id).equals(closing),"duplicate close reuses deadline");MarketStore.advancePendingForTests(300,102,due(closing));double cash=new JSONObject(MarketStore.book()).getDouble("cash");check(!pending(MarketStore.close(id)),"closed position rejected");check(cash==new JSONObject(MarketStore.book()).getDouble("cash"),"no double credit");MarketStore.tick(33,20,System.currentTimeMillis());check(!pending(MarketStore.open(33,true,10,151,good)),"per-market leverage cap");check(!pending(MarketStore.open(33,true,10,10,good.replace("\"fee\":0","\"fee\":-1"))),"negative fee rejected");MarketStore.tick(33,99,now-10000);check(MarketStore.priceOf(33)==20,"out-of-order tick ignored");MarketStore.tick(33,99,System.currentTimeMillis()+60000);check(MarketStore.priceOf(33)==20,"future quote ignored");MarketStore.tick(19,99,System.currentTimeMillis()-6000);check(!pending(MarketStore.open(19,true,10,10,good)),"stale quote rejected");MarketStore.reset();MarketStore.updateCaps("[{\"pairIndex\":33,\"minLeverage\":1.1,\"maxLeverage\":150},{\"pairIndex\":21,\"minLeverage\":10,\"maxLeverage\":1000}]");MarketStore.tick(33,100,System.currentTimeMillis());for(double lev:new double[]{1.1,1.101,149.999,150})check(pending(MarketStore.open(33,true,1,lev,good)),"allowed exact leverage "+lev);for(double lev:new double[]{1,1.099,150.001,1.1001})check(!pending(MarketStore.open(33,true,1,lev,good)),"invalid leverage "+lev);MarketStore.tick(21,100,System.currentTimeMillis());check(!pending(MarketStore.open(21,true,1,1.1,good)),"forex minimum enforced");check(pending(MarketStore.open(21,true,1,1000,good)),"forex max allowed");System.out.println("PASS: native delayed DEGEN lifecycle, open/close duplicate guards, dynamic leverage and quote validation.");}
}
